<script setup>import{computed,ref}from'vue';import{doubleBufferTimeline}from'./architectureModels.mjs';const enabled=ref(true),cycle=ref(0),rows=computed(()=>doubleBufferTimeline(enabled.value)),cols=computed(()=>rows.value[0].length-1);function toggle(){enabled.value=!enabled.value;cycle.value=0}</script>
<template><section class="db arch-overlay"><header><b>DOUBLE BUFFER TIMELINE</b><span>steady state = max(Tload, Tcompute)</span></header><div class="grid" :style="{'--cols':cols}"><template v-for="row in rows" :key="row[0]"><strong>{{row[0]}}</strong><i v-for="(v,j) in row.slice(1)" :key="j" :class="[row[0].toLowerCase(),{active:j===cycle}]">{{v}}</i></template></div><footer><button @click="toggle">{{enabled?'Disable':'Enable'}} overlap</button><button @click="cycle=(cycle+1)%cols">Step</button><button @click="cycle=0">Reset</button><b>{{enabled?'2 buffers · overlapped':'1 buffer · strictly serialized'}}</b></footer></section></template>
<style scoped>.db{right:0;bottom:0;width:700px;padding:18px;border-radius:20px}.db header,.db footer{display:flex;gap:10px;align-items:center;color:#adc3d8;font-size:12px}.db header{justify-content:space-between}.db header b{color:#17d9ff}.grid{display:grid;grid-template-columns:80px repeat(var(--cols),1fr);gap:6px;margin:18px 0}.grid strong,.grid i{display:grid;place-items:center;height:38px;border-radius:7px;font-size:12px}.grid strong{color:#9fb6ca}.grid i{background:#ffffff10;border:1px solid #ffffff14;font-style:normal}.grid i.load{color:#17d9ff}.grid i.compute{color:#ffbe00}.grid i.store{color:#b9ff33}.grid i.active{outline:2px solid white;box-shadow:0 0 12px #fff8}.db footer b{margin-left:auto;color:#f5f8ff}.db button{font-size:12px;padding:5px 9px}</style>
